// API-MED-02 escribe sin Idempotency-Key: la ruta firmada identifica la subida, y repetirla responde el mismo medio.
// API-TIE-01 tampoco: cada evento trae su identificador, y repetirlo responde lo mismo sin sumar.
// API-GOO-02 y 03 (DL-138) tampoco: vincular y crear con Google son idempotentes por la cuenta de Google.
const ESCRITURAS_SIN_CLAVE: ReadonlySet<string> = new Set(['API-TIE-01', 'API-CON-04', 'API-CON-08', 'API-EVI-04', 'API-NUT-10', 'API-NUT-11', 'API-ANT-10', 'API-TRN-10', 'API-TRN-11', 'API-TRN-15', 'API-TRN-17', 'API-TPL-05', 'API-TPN-05', 'API-HAB-02', 'API-HAB-05', 'API-HAB-08', 'API-HAN-02', 'API-HAN-05', 'API-HAN-08', 'API-MED-02', 'API-NOV-03', 'API-NOV-04', 'API-NOV-06', 'API-GOO-02', 'API-GOO-03', 'API-MET-02', 'API-MET-03', 'API-ADM-05', 'API-ADM-06', 'API-ADM-07', 'API-ADM-08', 'API-ADM-09']);

function conCodigosComunes(op: Operacion): Operacion {
  const errores: { -readonly [S in keyof Errores]: Errores[S] } = { ...op.errores };
  const sumar = (status: 409 | 429, codigo: Codigo) => {
    const actuales = errores[status] ?? [];
    if (!actuales.includes(codigo)) errores[status] = [...actuales, codigo];
  };
  if (op.idempotencia || ESCRITURAS_SIN_CLAVE.has(op.id)) sumar(409, 'RESOURCE_CONFLICT');
  if (LECTURAS_PROTEGIDAS.has(op.id)) sumar(429, 'RATE_LIMITED');
  return { ...op, errores };
}

export const OPERACIONES: readonly Operacion[] = DEFINIDAS.map(conCodigosComunes);

const aJson = (schema: z.ZodType) => z.toJSONSchema(schema, { target: 'draft-2020-12', io: 'input' });

export function documentoOpenApi(): Record<string, unknown> {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const op of OPERACIONES) {
    const parametros: Record<string, unknown>[] = [];
    for (const [, nombre] of op.ruta.matchAll(/\{([^}]+)\}/g)) {
      parametros.push({ name: nombre, in: 'path', required: true, schema: { type: 'string' } });
    }
    if (op.idempotencia) {
      parametros.push({
        name: 'Idempotency-Key',
        in: 'header',
        required: true,
        schema: { type: 'string', pattern: '^[A-Za-z0-9._:-]{8,128}$' },
      });
    }
    for (const q of op.query ?? []) {
      parametros.push({ name: q.nombre, in: 'query', required: q.obligatorio === true, description: q.descripcion, schema: q.schema });
    }
    parametros.push({
      name: 'X-BE-Surface',
      in: 'header',
      required: false,
      description: 'Superficie declarada (procedencia). Nunca autoriza (DEUDA_LEGAJO DL-022).',
      schema: { type: 'string', enum: ['WEB', 'APK'] },
    });
    parametros.push({
      name: HEADER_DE_CAPACIDADES,
      in: 'header',
      required: false,
      description:
        'Lo que el cliente sabe mostrar, separado por comas. Sin la cabecera, el cliente no muestra objetivos por serie y un plan que los exige no se le entrega (DL-122, precierre del 2026-10-06). Nunca autoriza.',
      schema: { type: 'string', maxLength: 256 },
    });
    const respuestas: Record<string, unknown> = {};
    for (const exito of op.exitos) {
      respuestas[exito.status] = exito.binario
        ? { description: 'Éxito', content: { [exito.binario]: { schema: { type: 'string', contentMediaType: exito.binario } } } }
        : exito.schema
          ? { description: 'Éxito', content: { 'application/json': { schema: aJson(exito.schema) } } }
          : { description: 'Éxito, sin cuerpo' };
    }
    for (const [status, codigos] of Object.entries(conComunes(op.errores))) {
      const detalles: Readonly<Record<string, Operacion['detalleDe422']>> = { '403': op.detalleDe403, '404': op.detalleDe404, '409': op.detalleDe409, '422': op.detalleDe422 };
      const detalle = detalles[status];
      const envelope = { $ref: '#/components/schemas/ErrorEnvelope' };
      respuestas[status] = {
        description: `ErrorEnvelope: ${(codigos ?? []).join(' | ')}${detalle ? `. ${detalle.codigo}: ${detalle.descripcion}` : ''}`,
        content: {
          'application/json': {
            schema: detalle
              ? { allOf: [envelope, { type: 'object', properties: { error: { type: 'object', properties: { details: aJson(detalle.schema) } } } }] }
              : envelope,
          },
        },
      };
    }
    paths[op.ruta] = {
      ...paths[op.ruta],
      [op.metodo]: {
        operationId: op.id,
        summary: op.resumen,
        description: `Fuente: ${op.fuente}. AuthN: ${op.autenticacion}.`,
        security: op.autenticacion === 'PUBLIC' || op.autenticacion === 'SIGNED_URL' ? [] : [{ sesion: [] }],
        parameters: parametros,
        ...(op.request
          ? { requestBody: { required: op.requestOpcional !== true, content: { 'application/json': { schema: aJson(op.request) } } } }
          : {}),
        ...(op.requestBinario
          ? { requestBody: { required: true, content: Object.fromEntries(op.requestBinario.map((t) => [t, { schema: { type: 'string', contentMediaType: t } }])) } }
          : {}),
        responses: respuestas,
      },
    };
  }
  return {
    openapi: '3.1.0',
    info: {
      title:
        'BE API — WP-02 Identidad y sesiones · WP-03 Vínculo, consentimiento y PDP · WP-04 Circuito nutricional · WP-05 Antropometría, métodos y cálculos · WP-06 Circuito de entrenamiento · WP-07 Información profesional pertinente · WP-08 Integraciones P0 · Recetas, medios privados y registro de comidas v2',
      version: '0.11.1',
      description:
        'Generado desde @be/domain (contratos.ts, contratos-vinculo.ts, contratos-nutricion.ts, contratos-antropometria.ts, contratos-calculo.ts, contratos-entrenamiento.ts, contratos-formularios.ts, contratos-procedencia-externa.ts, contratos-integraciones.ts, contratos-recetas.ts, contratos-medios.ts y contratos-registro-de-comidas.ts). No editar a mano.',
    },
    servers: [{ url: '/api/v1' }],
    components: {
      securitySchemes: {
        sesion: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT', description: 'Sesión revocable verificada en cada request (08 §26).' },
      },
      schemas: { ErrorEnvelope: aJson(ErrorEnvelopeSchema) },
    },
    paths,
  };
}

/** Códigos de error declarados para una operación (los propios más los comunes), por status. Lo usa el contract test. */
export function erroresDeclarados(id: string): Readonly<Record<string, readonly string[]>> {
  const op = OPERACIONES.find((o) => o.id === id);
  if (!op) throw new Error(`Operación no declarada: ${id}`);
  return conComunes(op.errores);
}

/** Busca la operación de una request real (método + ruta concreta con parámetros). Lo usa el contract test. */
export function operacionDe(metodo: string, rutaConcreta: string): Operacion | undefined {
  return OPERACIONES.find((o) => {
    if (o.metodo !== metodo) return false;
    const patron = new RegExp(`^/api/v1${o.ruta.replace(/\{[^}]+\}/g, '[^/]+')}$`);
    return patron.test(rutaConcreta);
  });
}
